from pathlib import Path
p=Path('frontend/src/app/features/verification/verify-result/verify-result.html'); s=p.read_text(encoding='utf-8-sig'); s=s.replace('</header>', '''</header>@if (lookup()?.headline) {<section class="surface"><span class="eyebrow">CLAIM UNDER REVIEW</span><h2 class="claim-preview">{{ lookup()!.headline }}</h2></section>}''',1); p.write_text(s,encoding='utf-8')
